#!/usr/bin/env python3
"""Differential fuzz: compare submission/main.py against tmp/ref.py."""
import sys, json, importlib.util, io, random, traceback
sys.path.insert(0, '/workspace/tmp')
import gen

def load(path, name):
    spec = importlib.util.spec_from_file_location(name, path)
    m = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(m)
    return m

main_mod = load('/workspace/submission/main.py', 'subm')
ref_mod = load('/workspace/tmp/ref.py', 'refm')

def run_main(text):
    try:
        return json.loads(json.dumps(main_mod.run(text)))
    except Exception:
        return {"error": "invalid-input"}

def run_ref(text):
    try:
        doc = json.loads(text)
        cfg, mdl, conns, pkts = ref_mod.check(doc)
        return json.loads(json.dumps(ref_mod.replay(cfg, mdl, conns, pkts)))
    except Exception:
        return {"error": "invalid-input"}

def diff_report(a, b, path=""):
    out = []
    if type(a) != type(b) and not (isinstance(a,(int,float)) and isinstance(b,(int,float))):
        out.append((path, a, b)); return out[:6]
    if isinstance(a, dict):
        for k in set(a) | set(b):
            if k not in a or k not in b:
                out.append((path + "/" + str(k), a.get(k, "<MISSING>"), b.get(k, "<MISSING>")))
            else:
                out += diff_report(a[k], b[k], path + "/" + str(k))
            if len(out) > 6: return out[:6]
    elif isinstance(a, list):
        if len(a) != len(b):
            out.append((path + ".len", len(a), len(b)))
        for i, (x, y) in enumerate(zip(a, b)):
            out += diff_report(x, y, path + "[%d]" % i)
            if len(out) > 6: return out[:6]
    else:
        if a != b:
            out.append((path, a, b))
    return out[:6]

def compare(text, tag):
    a = run_main(text)
    b = run_ref(text)
    if a != b:
        print("=== MISMATCH", tag)
        for p, x, y in diff_report(a, b):
            print("   ", p, "\n      got:", json.dumps(x)[:400], "\n      exp:", json.dumps(y)[:400])
        open('/workspace/tmp/fail_%s.json' % tag, 'w').write(text)
        return False
    return True

def main():
    lo = int(sys.argv[1]); hi = int(sys.argv[2])
    indent = int(sys.argv[3]) if len(sys.argv) > 3 else 0
    bad = 0
    for seed in range(lo, hi):
        doc = gen.gen(seed)
        text = json.dumps(doc, indent=indent) if indent else json.dumps(doc)
        if not compare(text, "s%d" % seed):
            bad += 1
            if bad > 4: break
    print("checked", hi - lo, "seeds, mismatches:", bad)

if __name__ == "__main__":
    main()
PYEOF
